// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    address deployer;

    function setUp() public {
        deployer = address(this);
        c = new Owned();
    }

    function testFuzz_property(address caller, address newOwner) public {

        bool ok;
        try c.setOwner(caller) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.assume(ok);

        bool secondCallSucceeded;
        vm.prank(caller);
        try c.setOwner(newOwner) {
            secondCallSucceeded = true;
        } catch {
            secondCallSucceeded = false;
        }

        assertTrue(caller == deployer || !secondCallSucceeded);
    }
}
